      "games.francotirador.title": "Sniper",
      "games.francotirador.description": "Five rounds of five shots at a distant target. Read the wind, correct your aim, hold your breath and score 1500 points to win 25,000.",
      "francotirador.eyebrow": "Read the wind, hold your breath, shoot",
      "francotirador.title": "Sniper",
      "francotirador.description": "Five rounds of five shots at a distant target. Every round brings its own distance, wind and landscape. Score enough points across all rounds and you earn the reward.",
      "francotirador.goalPrefix": "Goal",
      "francotirador.rule1": "A game is 5 rounds. Each round is {{shots}} shots at the same target, and its level (Easy, Medium or Hard) is drawn with equal probability. The farther the target, the harder it is.",
      "francotirador.rule2": "You have {{seconds}} seconds per shot. If the clock reaches zero, the rifle fires by itself with the scope wherever it is.",
      "francotirador.rule3": "Every shot is four things at once: aim (mouse or arrow keys and WASD), hold your breath (Shift, C or right button), correct for the wind (sometimes you must aim outside the target) and fire (space or click) just as the marker on the focus bar crosses the center.",
      "francotirador.rule4html": "The target has a bullseye and three rings: <strong>100, 50, 25 and 10 points</strong>. Missing the target scores nothing.",
      "francotirador.rule5html": "If you score <strong>{{goal}} points</strong> or more across the 5 rounds, you win <strong>{{points}} points</strong>. If you fall short, you get none.",
      "francotirador.startButton": "Start game",
